for control in data['controls']:
            base = next(row for row in report['rows'] if row['id'] == control['case'])
            poison = copy.deepcopy(base['results']['Guest'])
            values = poison['calls']['values'][0]['values']
            kind = control['id']
            if kind == 'value': values[1]['value'] += 1
            elif kind == 'type': values[1] = dict(type='bool',value=True)
            elif kind == 'arity': values.append(dict(type='str',value='extra'))
            elif kind == 'port-order': values[0],values[2] = values[2],values[0]
            elif kind == 'trim-retained': values[2]['value'] = values[2]['value'].strip()
            elif kind == 'LF-only-boundary':
                # Counterfactual applied to actual captured input/result, never
                # substituted for the pristine native oracle.
                captured_input = poison['inputs_before']['items'][0][1]['values'][0]['value']
                wrong_lines = [line for line in captured_input.split('\n') if line.strip()]
                values[1]['value'] = len(wrong_lines)
                values[2]['value'] = '\n'.join(wrong_lines)
            elif kind == 'aggregate-order':
                a = poison['aggregate']['values'][0]['values']; a[0],a[1] = a[1],a[0]
            elif kind == 'input-side-effect': poison['inputs_after']['items'].append(['unexpected',dict(type='str',value='changed')])
            else: raise AssertionError('Unknown control')
            try:
                validate(poison,base['expected'])
            except AssertionError as error:
                report['controls'].append(dict(id=kind,case=control['case'],detected=True,message=str(error),additional_dispatches=0))
            else: raise AssertionError('Wrong-result control survived '+kind)
